solutionCode:
fun getLength(text: String?): Int {
    return text?.length ?: 0
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testWithString() {
        Assert.assertEquals(7, getLength("Tribots"))
    }

    @Test
    fun testWithNull() {
        Assert.assertEquals(0, getLength(null))
    }

    @Test
    fun testWithEmptyString() {
        Assert.assertEquals(0, getLength(""))
    }

    @Test
    fun testWithLongString() {
        Assert.assertEquals(13, getLength("Team 4215 FRC"))
    }
}
